pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant INIT = 1;

    function setUp() public {
        c = new C();
        Log lg = new Log();
        c.SetLogFile(address(lg));
        c.SetMinSum(INIT);
        c.Initialized();
    }

    function testFuzz_property(uint256 newVal, uint256 am) public {
        vm.assume(newVal != INIT);
        am = bound(am, 1, 10 ether);
        vm.warp(block.timestamp + 1);

        ReentrantAttacker attacker = new ReentrantAttacker(c, newVal);
        vm.deal(address(attacker), am);
        vm.prank(address(attacker));
        c.Put{value: am}(0);

        uint256 minSumBefore = c.MinSum();
        attacker.attack(am);

        // Rule: a reentrant SetMinSum from within Collect must never change MinSum.
        assertTrue(c.MinSum() == minSumBefore);
    }
}

contract Log {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

contract ReentrantAttacker {
    C c;
    uint256 v;

    constructor(C _c, uint256 _v) {
        c = _c;
        v = _v;
    }

    function attack(uint256 am) public {
        c.Collect(am);
    }

    receive() external payable {
        c.SetMinSum(v);
    }
}

