pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 newVal) public {
        vm.assume(amount > 0);

        c.SetLogFile(address(new Logger()));
        c.SetMinSum(0);

        Attacker a = new Attacker(c);
        vm.deal(address(a), amount);

        // deposit via fallback -> Put(0), unlockTime = block.timestamp
        a.deposit(amount);

        // make block.timestamp > unlockTime so Collect may proceed
        vm.warp(block.timestamp + 1);

        // Collect pays the attacker; attacker's receive() re-enters SetMinSum(newVal)
        a.withdraw(newVal);

        // Rule: MinSum set before any Collect is never changed by a reentrant SetMinSum.
        assertTrue(c.MinSum() == 0);
    }
}

contract Logger {
    function AddMessage(address, uint256, string calldata) external pure {}
}

contract Attacker {
    C c;
    uint256 newVal;
    constructor(C _c) { c = _c; }
    function deposit(uint256 amount) external payable {
        (bool s,) = address(c).call{value: amount}("");
        s;
    }
    function withdraw(uint256 v) external {
        newVal = v;
        c.Collect(v);
    }
    receive() external payable {
        // re-entrant attempt; must revert on the locked contract
        c.SetMinSum(newVal);
    }
}

