pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 val, address actor) public {
        // Admissible domain: any value where _val + 1 does not overflow uint256.
        vm.assume(val < type(uint256).max);
        vm.assume(actor != address(0));

        vm.prank(actor);
        c.SetMinSum(val);

        // General rule: SetMinSum stores exactly the supplied value in MinSum.
        assertTrue(c.MinSum() == val);
    }
}

